document.addEventListener("DOMContentLoaded", () => {
  const e = document.querySelector(".menu-toggle"),
    t = document.querySelector(".mobile-menu"),
    n = e?.querySelector("span");
  let r = null;
  const i = (i = !1) => {
    e &&
      t &&
      ((t.hidden = !0),
      e.setAttribute("aria-expanded", "false"),
      (n.textContent = "Menu"),
      document.body.classList.remove("menu-open"),
      i && r && r.focus());
  };
  (e?.addEventListener("click", () => {
    "true" === e.getAttribute("aria-expanded")
      ? i()
      : e &&
        t &&
        ((r = document.activeElement),
        (t.hidden = !1),
        e.setAttribute("aria-expanded", "true"),
        (n.textContent = "Close"),
        document.body.classList.add("menu-open"),
        t.querySelector("a")?.focus());
  }),
    t
      ?.querySelectorAll("a")
      .forEach((e) => e.addEventListener("click", () => i())),
    document.addEventListener("keydown", (t) => {
      "Escape" === t.key &&
        "true" === e?.getAttribute("aria-expanded") &&
        i(!0);
    }),
    window.addEventListener("resize", () => {
      window.innerWidth > 900 && i();
    }));
  const o = [...document.querySelectorAll(".desktop-nav a[href^='#']")],
    a = o
      .map((e) => document.querySelector(e.getAttribute("href")))
      .filter(Boolean);
  if ("IntersectionObserver" in window) {
    const e = new IntersectionObserver(
      (e) => {
        const t = e
          .filter((e) => e.isIntersecting)
          .sort((e, t) => t.intersectionRatio - e.intersectionRatio)[0];
        t &&
          o.forEach((e) => {
            e.getAttribute("href") === `#${t.target.id}`
              ? e.setAttribute("aria-current", "true")
              : e.removeAttribute("aria-current");
          });
      },
      { rootMargin: "-25% 0px -60%", threshold: [0, 0.1, 0.4] },
    );
    a.forEach((t) => e.observe(t));
  }
  const d = document.querySelector(".contact-form");
  if (!d) return;
  const s = d.querySelector(".form-status"),
    c = d.querySelector(".submit-button"),
    l = c.querySelector("span"),
    u = [
      ...d.querySelectorAll(
        "input[required], select[required], textarea[required]",
      ),
    ],
    m = (e) => {
      const t = document.getElementById(e.getAttribute("aria-describedby"));
      if (!t) return;
      const n = e.validity.valid
        ? ""
        : ((e) =>
            e.validity.valueMissing
              ? `${e.labels[0].textContent} is required.`
              : e.validity.typeMismatch
                ? "Enter a valid email address."
                : e.validity.tooShort
                  ? `Please use at least ${e.minLength} characters.`
                  : "Please check this field.")(e);
      ((t.textContent = n),
        e.setAttribute("aria-invalid", String(!e.validity.valid)));
    };
  (u.forEach((e) => {
    (e.addEventListener("blur", () => m(e)),
      e.addEventListener("input", () => {
        "true" === e.getAttribute("aria-invalid") && m(e);
      }),
      e.addEventListener("change", () => m(e)));
  }),
    d.addEventListener("submit", async (e) => {
      (e.preventDefault(), u.forEach(m));
      const t = u.find((e) => !e.validity.valid);
      if (t)
        return (
          (s.textContent =
            "Please correct the highlighted fields before sending."),
          void t.focus()
        );
      const n = window.EMAILJS_CONFIG || {};
      if (!n.serviceId || !n.templateId || !n.publicKey)
        return void (s.textContent =
          "Email delivery is not configured yet. Please contact Emmanuel by email or WhatsApp.");
      const r = d.querySelector("[name='_honey']");
      if (r?.value.trim())
        return void (s.textContent =
          "This enquiry could not be sent. Please contact Emmanuel directly.");
      ((s.textContent = "Submitting your enquiry securely…"),
        (c.disabled = !0),
        (l.textContent = "Sending…"));
      const i = new FormData(d),
        o = {
          from_name: String(i.get("from_name") || ""),
          reply_to: String(i.get("reply_to") || ""),
          service: String(i.get("service") || ""),
          budget: String(i.get("budget") || "Not sure yet"),
          message: String(i.get("message") || ""),
          submitted_at: new Date().toISOString(),
          page_url: window.location.href,
        };
      try {
        if (
          !(
            await fetch("https://api.emailjs.com/api/v1.0/email/send", {
              method: "POST",
              headers: { "Content-Type": "application/json" },
              body: JSON.stringify({
                service_id: n.serviceId,
                template_id: n.templateId,
                user_id: n.publicKey,
                template_params: o,
              }),
            })
          ).ok
        )
          throw new Error("EmailJS rejected the enquiry.");
        ((s.textContent =
          "Your enquiry has been sent successfully. Redirecting…"),
          d.reset(),
          u.forEach((e) => e.setAttribute("aria-invalid", "false")),
          d.querySelectorAll(".error").forEach((e) => {
            e.textContent = "";
          }),
          window.setTimeout(
            () => window.location.assign("thank-you.html"),
            700,
          ));
      } catch {
        ((s.textContent =
          "Your enquiry could not be sent. Please try again or contact Emmanuel by email or WhatsApp."),
          (c.disabled = !1),
          (l.textContent = "Send Project Enquiry"));
      }
    }),
    window.addEventListener("pageshow", () => {
      ((c.disabled = !1), (l.textContent = "Send Project Enquiry"));
    }));
});
